.darma-loader-darma-b13-padlock-click { --accent: var(--loader-color, #1d4ed8); --accent-2: var(--loader-secondary-color, #94a3b8); width: calc(var(--loader-size, 96px) * .68); height: var(--loader-size, 96px); position: relative; }
.darma-loader-darma-b13-padlock-click::after { content: ''; position: absolute; z-index: 2; bottom: 0; left: 0; width: 100%; height: 56%; border-radius: 14%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 26%, var(--accent))); }
.darma-loader-darma-b13-padlock-click::before { content: ''; position: absolute; z-index: 3; bottom: 18%; left: 40%; width: 20%; height: 22%; border-radius: 50% 50% 22% 22%; background: color-mix(in srgb, #000 50%, var(--accent)); }
.darma-loader-darma-b13-padlock-click span { position: absolute; z-index: 1; bottom: 44%; left: 19%; width: 62%; height: 50%; border: calc(var(--loader-size, 96px) * .1) solid var(--accent-2); border-bottom: 0; border-radius: 999px 999px 0 0; animation: darma-loader-darma-b13-padlock-click-unlatch calc(var(--loader-speed, 1s) * 2.2) cubic-bezier(.5, 0, .3, 1) infinite; }
@keyframes darma-loader-darma-b13-padlock-click-unlatch { 0%, 20% { transform: translateY(0); } 46%, 62% { transform: translateY(-26%); } 88%, 100% { transform: translateY(0); } }

